import { Menu, X } from 'lucide-react';
import { useState } from 'react';

export default function Navbar({ logo = 'Brand', links = [], className = '', ...props }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <nav className={`backdrop-blur-xl bg-white/5 border-b border-white/10 sticky top-0 z-50 ${className}`} {...props}>
      <div className="mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <span className="text-xl font-bold bg-gradient-to-r from-violet-400 to-cyan-400 bg-clip-text text-transparent">
              {logo}
            </span>
          </div>

          <div className="hidden md:block">
            <div className="ml-10 flex items-baseline space-x-4">
              {links.map((link, i) => (
                <a
                  key={i}
                  href={link.href || '#'}
                  className="text-gray-300 hover:text-white hover:bg-white/10 px-3 py-2 rounded-lg transition-all duration-200"
                >
                  {link.label}
                </a>
              ))}
            </div>
          </div>

          <div className="md:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="text-gray-300 hover:text-white p-2"
            >
              {isOpen ? <X /> : : <Menu />}
            </button>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="md:hidden">
          <div className="px-2 pt-2 pb-3 space-y-1">
            {links.map((link, i) => (
              <a
                key={i}
                href={link.href || '#'}
                className="text-gray-300 hover:text-white hover:bg-white/10 block px-3 py-2 rounded-lg"
              >
                {link.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
}
